// The customer-facing catalogue should never offer an "Out of stock" facet.
// Keep stock status itself intact for product cards, cart validation, and quote flows.
const isOutOfStockFilterLabel=(label:string)=>/^out\s+of\s+stock\b/i.test(label.trim());
const activeFacetSelections=(selected:Record<string,AppliedFacet>)=>Object.values(selected).filter(item=>!isOutOfStockFilterLabel(item.label));
const activeFacetInputs=(selected:Record<string,AppliedFacet>)=>activeFacetSelections(selected).map(item=>item.input);
const quoteSearchValue=(value:unknown)=>`"${String(value).replace(/\\/g,"\\\\").replace(/"/g,'\\"')}"`;
function productQueryFromFacets(selected:Record<string,AppliedFacet>):string{
 const terms:string[]=[];
 for(const item of activeFacetSelections(selected)){
  const input=item.input as Record<string,unknown>|null;
  if(!input||typeof input!=="object")continue;
  if(typeof input.available==="boolean")terms.push(`available_for_sale:${input.available}`);
  if(typeof input.productVendor==="string"&&input.productVendor.trim())terms.push(`vendor:${quoteSearchValue(input.productVendor.trim())}`);
  if(typeof input.productType==="string"&&input.productType.trim())terms.push(`product_type:${quoteSearchValue(input.productType.trim())}`);
  if(typeof input.productTags==="string"&&input.productTags.trim())terms.push(`tag:${quoteSearchValue(input.productTags.trim())}`);
  if(typeof input.tag==="string"&&input.tag.trim())terms.push(`tag:${quoteSearchValue(input.tag.trim())}`);
  const price=input.price as {min?:number|string;max?:number|string}|undefined;
  if(price){
   const min=price.min==null?null:Number(price.min);const max=price.max==null?null:Number(price.max);
   if(min!==null&&Number.isFinite(min))terms.push(`variants.price:>=${min}`);
   if(max!==null&&Number.isFinite(max))terms.push(`variants.price:<=${max}`);
  }
 }
 return terms.join(" AND ");
}


