function brandKey(name:string):string{return name.trim().toLowerCase().replace(/&/g,"and").replace(/[^a-z0-9]+/g," ").trim().replace(/\s+/g," ")}
const money=(m?:Money|null)=>{if(!m)return "Get Quote";const n=Number(m.amount);if(!Number.isFinite(n)||n<=0)return "Get Quote";return `${m.currencyCode==="AED"?"AED":m.currencyCode} ${n.toFixed(2)}`};
const slugify=(s:string)=>s.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
const titleFromSlug=(s:string)=>s.split("-").filter((x):x is string=>Boolean(x)).map((x:string)=>x[0]?.toUpperCase()+x.slice(1)).join(" ");
const isVariantPurchasable=(v?:Variant|null)=>!!v&&v.availableForSale&&!v.currentlyNotInStock&&(typeof v.quantityAvailable!=="number"||v.quantityAvailable>0);
const firstPurchasableVariant=(p:Product)=>p.variants.find(isVariantPurchasable)||p.variants[0];
const lowStockLabel=(v?:Variant|null)=>typeof v?.quantityAvailable==="number"&&v.quantityAvailable>0&&v.quantityAvailable<10?`Only ${v.quantityAvailable} left`:null;
const variantOutOfStock=(v?:Variant|null)=>!!v&&(!v.availableForSale||!!v.currentlyNotInStock||(typeof v.quantityAvailable==="number"&&v.quantityAvailable<=0));
const cartLineStockIssue=(line?:CartLine|null)=>{const max=line?.merchandise.quantityAvailable;return !!line?.merchandise.currentlyNotInStock||(typeof max==="number"&&(max<=0||line!.quantity>max))};
const cartLineStockMessage=(line?:CartLine|null)=>{if(!line)return null;const max=line.merchandise.quantityAvailable;if(line.merchandise.currentlyNotInStock||typeof max==="number"&&max<=0)return "Out of stock · Request a quote";if(typeof max!=="number")return null;if(line.quantity>max)return `Only ${max} left in stock · Reduce quantity`;return max<10?`Only ${max} left`:null};
const cartHasStockIssue=(cart?:Cart|null)=>!!cart?.lines.some(cartLineStockIssue);
function useBodyScrollLock(active:boolean){
 useEffect(()=>{if(!active)return;const previous=document.body.style.overflow;document.body.style.overflow="hidden";return()=>{document.body.style.overflow=previous}},[active]);
}

function handleNativeWheel(e:ReactWheelEvent<HTMLElement>){
 const el=e.currentTarget;
 if(!e.deltaY)return;
 // Let the native element scroll; do not manually mutate scrollTop or cancel the event.
 // The page can resume scrolling when this nested surface reaches its top/bottom boundary.
 const max=Math.max(0,el.scrollHeight-el.clientHeight);
 if(max<=1)return;
 const delta=e.deltaMode===1?e.deltaY*16:e.deltaMode===2?e.deltaY*el.clientHeight:e.deltaY;
 const atTop=el.scrollTop<=0;
 const atBottom=el.scrollTop>=max-1;
 const canMove=(delta<0&&!atTop)||(delta>0&&!atBottom);
 if(canMove)e.stopPropagation();
}

async function shopifyFetch<T>(query:string,variables:Record<string,unknown>={}):Promise<T>{
  const request=async(q:string):Promise<T>=>{
    const controller=new AbortController();
    const timeout=window.setTimeout(()=>controller.abort(),20000);
    try{
      const r=await fetch("/api/shopify",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({query:q,variables}),cache:"no-store",signal:controller.signal});
      const j=await r.json().catch(()=>null);
      if(!r.ok||j?.errors?.length)throw new Error("Shopify request failed");
      return j.data;
    }catch(error){
      if(error instanceof DOMException&&error.name==="AbortError")throw new Error("Shopify request timed out");
      throw error;
    }finally{window.clearTimeout(timeout)}
  };
  try{return await request(query)}catch(error){
    if(error instanceof Error&&error.message==="Shopify request failed"&&/\bquantityAvailable\b/.test(query)){
      const fallback=query.replace(/\bquantityAvailable\b/g,"");
      return request(fallback);
    }
    throw error;
  }
}

