function normalize(raw:any):Product{
 const variants=(raw?.variants?.nodes||[]).map((v:any)=>({id:v.id,title:v.title,availableForSale:!!v.availableForSale,currentlyNotInStock:!!v.currentlyNotInStock,sku:v.sku,price:v.price,compareAtPrice:v.compareAtPrice,selectedOptions:v.selectedOptions||[],image:v.image,quantityAvailable:typeof v.quantityAvailable==="number"?v.quantityAvailable:null}));
 const images=raw?.images?.nodes?.length?raw.images.nodes:(raw?.featuredImage?[raw.featuredImage]:[]);
 const rating=Number(raw?.reviewRating?.value); const reviewCount=Number(raw?.reviewRatingCount?.value); const boughtCount=Number(raw?.boughtCount?.value);
 return {id:raw.id,handle:raw.handle,name:raw.title,brand:raw.vendor||"BuyHoreca",description:raw.description||"",descriptionHtml:raw.descriptionHtml,productType:raw.productType,price:raw.priceRange?.minVariantPrice||variants[0]?.price||{amount:"0",currencyCode:"AED"},compareAtPrice:variants[0]?.compareAtPrice,availableForSale:!!raw.availableForSale,images,variants,href:`/products/${raw.handle}`,rating:Number.isFinite(rating)?rating:undefined,reviewCount:Number.isFinite(reviewCount)?reviewCount:undefined,boughtCount:Number.isFinite(boughtCount)?boughtCount:undefined,seo:raw.seo};
}
const normCart=(raw:any):Cart|null=>raw?{id:raw.id,checkoutUrl:raw.checkoutUrl,totalQuantity:raw.totalQuantity,discountCodes:(raw.discountCodes||[]).map((d:any)=>({code:d.code,applicable:!!d.applicable})),cost:raw.cost,lines:(raw.lines?.nodes||[]).filter(Boolean).map((l:any)=>({id:l.id,quantity:l.quantity,merchandise:{id:l.merchandise.id,title:l.merchandise.title,price:l.merchandise.price,image:l.merchandise.image,currentlyNotInStock:!!l.merchandise.currentlyNotInStock,quantityAvailable:typeof l.merchandise.quantityAvailable==="number"?l.merchandise.quantityAvailable:null,product:l.merchandise.product}}))}:null;
