function normalizeArticle(raw:any):BlogArticle{const tags=Array.isArray(raw?.tags)?raw.tags.filter((x:any):x is string=>typeof x==="string"):[];return {id:raw.id,handle:raw.handle,title:raw.title,excerpt:raw.excerpt,excerptHtml:raw.excerptHtml,contentHtml:raw.contentHtml||"",publishedAt:raw.publishedAt,image:raw.image,tags,blogHandle:raw.blog?.handle||"",blogTitle:raw.blog?.title||"",seo:raw.seo};}
async function fetchConnectionPages<T>(query:string,variables:Record<string,unknown>,connectionPath:string,first=250):Promise<T[]>{
 return collectPages<T>(async(after)=>{
  const data:any=await shopifyFetch(query,{...variables,first,after});
  return connectionPageFrom<T>(data,connectionPath)||{nodes:[],pageInfo:{hasNextPage:false,endCursor:null}};
 });
}
async function getHomeArticles():Promise<BlogArticle[]>{
 const data:any=await shopifyFetch(HOME_BLOGS,{first:20});
 return (data.blogs?.nodes||[]).flatMap((blog:any)=>(blog.articles?.nodes||[]).map((article:any)=>({...normalizeArticle(article),blogHandle:blog.handle,blogTitle:blog.title}))).sort((a:BlogArticle,b:BlogArticle)=>new Date(b.publishedAt).getTime()-new Date(a.publishedAt).getTime()).slice(0,12);
}
async function getBlogs():Promise<Blog[]>{
 const blogNodes=await fetchConnectionPages<any>(BLOGS,{},"blogs",50);
 // Load article previews page-by-page so older posts and newly-created blogs are not
 // silently omitted by the previous fixed 20-blog / 20-article limit.
 const blogs:Blog[]=[];
 for(const blog of blogNodes){
  const articleNodes=await fetchConnectionPages<any>(BLOG_ARTICLES,{handle:blog.handle},"blog.articles",250);
  blogs.push({id:blog.id,handle:blog.handle,title:blog.title,articles:articleNodes.map((article:any)=>({...normalizeArticle(article),blogHandle:blog.handle,blogTitle:blog.title}))});
 }
 return blogs;
}
