function PolicyPage({handle}:{handle:string}){
 const config=POLICY_ROUTES[handle]||POLICY_ROUTES["privacy-policy"];
 const [policy,setPolicy]=useState<StorePolicy|null>(null);
 const [status,setStatus]=useState<"loading"|"ready"|"error">("loading");
 const [attempt,setAttempt]=useState(0);
 useEffect(()=>{let active=true;setStatus("loading");shopifyFetch<{shop?:Record<string,StorePolicy|null|undefined>}>(SHOP_POLICIES_QUERY).then(data=>{if(!active)return;const found=data.shop?.[config.key]||null;setPolicy(found);setStatus("ready")}).catch(()=>{if(active){setPolicy(null);setStatus("error")}});return()=>{active=false}},[config.key,attempt]);
 const body=policyHtmlToText(policy?.body||"");
 return <main className="mx-auto max-w-4xl px-4 py-10 md:py-14"><header className="border-b border-slate-200 pb-6"><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">BuyHoreca policies</div><h1 className="mt-2 text-3xl font-semibold text-[#0f2630] md:text-4xl">{policy?.title||config.title}</h1><p className="mt-3 max-w-3xl text-sm leading-6 text-slate-600">{config.description}</p></header>{status==="loading"?<div className="mt-6 rounded border border-slate-200 bg-slate-50 p-5 text-sm text-slate-600" role="status">Loading the policy published in Shopify…</div>:status==="error"?<div className="mt-6 rounded border border-amber-200 bg-amber-50 p-5"><p className="text-sm leading-6 text-amber-900">We could not load this policy from Shopify. Please retry or contact BuyHoreca for assistance.</p><button type="button" onClick={()=>setAttempt(value=>value+1)} className="mt-3 rounded border border-amber-300 bg-white px-4 py-2 text-sm font-semibold text-amber-950">Retry</button></div>:!policy||!body?<div className="mt-6 rounded border border-amber-200 bg-amber-50 p-5"><h2 className="font-semibold text-amber-950">This policy has not been published in Shopify</h2><p className="mt-2 text-sm leading-6 text-amber-900">BuyHoreca must add and approve this policy in Shopify Admin before it can be shown here. Please contact the team for current information.</p><a href="mailto:info@buyhoreca.com" className="mt-4 inline-flex rounded border border-amber-300 bg-white px-4 py-2 text-sm font-semibold text-amber-950">Contact BuyHoreca</a></div>:<article className="mt-6 rounded border border-slate-200 bg-white p-5 md:p-8"><p className="whitespace-pre-wrap break-words text-sm leading-7 text-slate-700">{body}</p>{policy.url&&<a href={policy.url} target="_blank" rel="noopener noreferrer" className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-[#008f68] underline underline-offset-4">View the published Shopify policy <ArrowRight size={14}/></a>}</article>}</main>
}

