function BlogRail({articles}:{articles:BlogArticle[]}){
 const carousel=useRef<HTMLDivElement>(null);
 const track=useRef<HTMLDivElement>(null);
 const group=useRef<HTMLDivElement>(null);
 // Keep the travelled distance in the stable range [0, one group width).
 // Mixing negative animation offsets with positive button offsets caused direction
 // reversals/jumps after using the arrows or after a resize.
 const offsetRef=useRef(0);
 const previousCycleRef=useRef(0);
 const [paused,setPaused]=useState(false);
 const [autoSlide,setAutoSlide]=useState(true);
 const [reducedMotion,setReducedMotion]=useState(false);
 const [copyCount,setCopyCount]=useState(2);
 const items=articles;
 const pause=()=>setPaused(true), resume=()=>setPaused(false);
 const cycleWidth=useCallback(()=>group.current?.getBoundingClientRect().width||0,[]);
 const applyTransform=useCallback(()=>{
   const el=track.current;
   const cycle=cycleWidth();
   if(!el||cycle<=0)return;
   offsetRef.current=((offsetRef.current%cycle)+cycle)%cycle;
   el.style.transform=`translate3d(${-offsetRef.current}px,0,0)`;
 },[cycleWidth]);
 useEffect(()=>{
   const media=window.matchMedia("(prefers-reduced-motion: reduce)");
   const update=()=>setReducedMotion(media.matches);
   update();
   media.addEventListener?.("change",update);
   return()=>media.removeEventListener?.("change",update);
 },[]);
 useEffect(()=>{
   const measure=()=>{
     const viewport=carousel.current?.clientWidth||0;
     const cycle=cycleWidth();
     if(viewport<=0||cycle<=0)return;
     const previousCycle=previousCycleRef.current;
     if(previousCycle>0&&Math.abs(previousCycle-cycle)>0.5){
       // Preserve loop progress through responsive card-width changes instead of
       // snapping the track back to the left edge on every ResizeObserver callback.
       offsetRef.current=(offsetRef.current/previousCycle)*cycle;
     }
     previousCycleRef.current=cycle;
     const needed=Math.max(2,Math.ceil(viewport/cycle)+1);
     setCopyCount(current=>current===needed?current:needed);
     offsetRef.current=((offsetRef.current%cycle)+cycle)%cycle;
     applyTransform();
   };
   measure();
   const observer=typeof ResizeObserver!=="undefined"?new ResizeObserver(measure):null;
   if(carousel.current)observer?.observe(carousel.current);
   if(group.current)observer?.observe(group.current);
   window.addEventListener("resize",measure);
   return()=>{observer?.disconnect();window.removeEventListener("resize",measure)};
 },[items.length,cycleWidth,applyTransform]);
 const nudge=(direction:number)=>{
   const g=group.current;
   if(!g||!items.length)return;
   const card=g.querySelector<HTMLElement>("[data-blog-card]");
   const styles=getComputedStyle(g);
   const gap=parseFloat(styles.columnGap||styles.gap||"0")||0;
   const step=(card?.getBoundingClientRect().width||280)+gap;
   if(reducedMotion){carousel.current?.scrollBy({left:direction*step,behavior:"auto"});return}
   const cycle=cycleWidth();
   if(cycle<=0)return;
   offsetRef.current=((offsetRef.current+direction*step)%cycle+cycle)%cycle;
   applyTransform();
 };
 useEffect(()=>{
   const t=track.current;
   if(!t||!group.current||items.length===0||paused||!autoSlide||reducedMotion)return;
   let frame=0,last=performance.now();
   const tick=(now:number)=>{
     const dt=Math.min(50,Math.max(0,now-last));last=now;
     const cycle=cycleWidth();
     if(cycle>0){
       offsetRef.current=(offsetRef.current+18*(dt/1000))%cycle;
       t.style.transform=`translate3d(${-offsetRef.current}px,0,0)`;
     }
     frame=requestAnimationFrame(tick);
   };
   frame=requestAnimationFrame(tick);
   return()=>cancelAnimationFrame(frame);
 },[items.length,paused,autoSlide,reducedMotion,copyCount,cycleWidth]);
 if(!items.length)return null;
 const renderCard=(a:BlogArticle,copy:number,index:number)=><Link key={`${a.id}-${copy}`} data-blog-card data-blog-copy={String(copy)} data-blog-index={String(index)} tabIndex={copy===0?0:-1} aria-hidden={copy>0?true:undefined} href={`/blog/${a.blogHandle}/${a.handle}`} onMouseEnter={pause} onMouseLeave={resume} onFocus={pause} onBlur={(e)=>{if(!e.currentTarget.contains(e.relatedTarget as Node|null))resume()}} className="bh-blog-card group shrink-0 overflow-hidden rounded border border-slate-200 bg-white">
   <div className="aspect-[16/9] overflow-hidden bg-slate-100">{a.image?<img src={a.image.url} alt={a.image.altText||a.title} loading="lazy" decoding="async" className="h-full w-full object-cover transition duration-500 group-hover:scale-105"/>:<div className="grid h-full place-items-center text-slate-400"><BookOpen/></div>}</div>
   <div className="p-4"><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider text-slate-500"><CalendarDays size={12}/>{new Date(a.publishedAt).toLocaleDateString()}</div><h3 className="mt-2 line-clamp-2 text-base font-bold leading-5 group-hover:text-[#008f68]">{a.title}</h3><p className="mt-2 line-clamp-2 text-xs leading-5 text-slate-500">{a.excerpt||"Read the latest hospitality and foodservice insights from BuyHoreca."}</p><span className="mt-3 inline-flex items-center gap-1 text-xs font-semibold text-[#008f68]">Read article <ArrowRight size={13}/></span></div>
  </Link>;
 return <section className="mx-auto max-w-[1920px] px-4 py-8"><div className="rounded border border-slate-200 bg-[#fbfcfb] p-5 md:p-6"><div className="flex items-end justify-between gap-4"><div><div className="text-[10px] font-semibold uppercase tracking-[.16em] text-slate-500">From BuyHoreca</div><h2 className="mt-1 text-[24px] font-bold">Hospitality insights</h2><p className="mt-1 text-sm text-slate-500">Latest articles from the BuyHoreca Shopify blog.</p></div><div className="flex items-center gap-2"><button type="button" onClick={()=>nudge(-1)} className="bh-carousel-arrow" aria-label="Previous articles"><ChevronLeft size={17}/></button><button type="button" onClick={()=>nudge(1)} className="bh-carousel-arrow" aria-label="Next articles"><ChevronRight size={17}/></button><Link href="/blog" className="hidden text-sm font-bold text-[#008f68] sm:inline">View all articles <ArrowRight size={14} className="inline"/></Link></div></div>
  <div ref={carousel} className="bh-blog-carousel mt-5 pb-1" role="region" aria-label="Latest BuyHoreca articles"><div ref={track} className="bh-blog-track">{Array.from({length:copyCount},(_,copy)=><div key={`blog-group-${copy}`} ref={copy===0?group:undefined} className={`bh-blog-group ${copy>0?"bh-blog-group-duplicate":""}`} aria-label={copy===0?"Latest articles":undefined} aria-hidden={copy>0?true:undefined}>{items.map((a,i)=>renderCard(a,copy,i))}</div>)}</div></div>
  <div className="mt-3 flex items-center justify-between gap-3 text-[11px] text-slate-400"><span>{reducedMotion?"Reduced motion is enabled — use the arrows or swipe":paused?"Paused — move away to continue":autoSlide?"Auto-sliding continuously · hover a card to pause":"Auto-slide paused"}</span><button type="button" onClick={()=>setAutoSlide(x=>!x)} className="text-[11px] font-semibold text-[#008f68] disabled:cursor-not-allowed disabled:opacity-60" aria-label={reducedMotion?"Automatic motion disabled by your reduced-motion setting":autoSlide?"Pause article auto-scroll":"Resume article auto-scroll"} aria-pressed={autoSlide} disabled={reducedMotion}>{reducedMotion?"Reduced motion":autoSlide?"Pause":"Play"}</button><span className="hidden sm:inline">{reducedMotion?"Swipe or use arrows":"Hover any card to pause"}</span></div><Link href="/blog" className="mt-3 inline-flex text-sm font-bold text-[#008f68] sm:hidden">View all articles <ArrowRight size={14} className="ml-1"/></Link></div></section>
}

function BlogIndex(){
 const [blogs,setBlogs]=useState<Blog[]>([]); const [loading,setLoading]=useState(true); const [term,setTerm]=useState(""); const [tag,setTag]=useState("All");
 useEffect(()=>{getBlogs().then(setBlogs).catch(()=>setBlogs([])).finally(()=>setLoading(false))},[]);
 const articles=useMemo(()=>blogs.flatMap(b=>b.articles.map(a=>({...a,blogHandle:b.handle,blogTitle:b.title}))).sort((a,b)=>new Date(b.publishedAt).getTime()-new Date(a.publishedAt).getTime()),[blogs]);
 const tags=useMemo(()=>["All",...Array.from(new Set(articles.flatMap(a=>a.tags))).sort((a,b)=>a.localeCompare(b))],[articles]);
 const filtered=useMemo(()=>{const q=term.trim().toLowerCase();return articles.filter(a=>(tag==="All"||a.tags.includes(tag))&&(!q||`${a.title} ${a.excerpt||""} ${a.blogTitle} ${a.tags.join(" ")}`.toLowerCase().includes(q)))},[articles,term,tag]);
 return <main className="mx-auto max-w-[1920px] px-4 py-8">
  <div className="border-b border-slate-200 pb-6"><div className="text-[10px] font-semibold uppercase tracking-[.16em] text-[#008f68]">BuyHoreca Journal</div><h1 className="mt-2 text-3xl font-semibold md:text-4xl">Hospitality Insights</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">Product guidance, hospitality ideas, kitchen operations and foodservice insights published through your Shopify blog.</p></div>
  {!loading&&articles.length>0&&<div className="mt-6 grid gap-3 lg:grid-cols-[1fr_auto]"><label className="relative block"><span className="sr-only">Search blog articles</span><Search className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={15}/><input value={term} onChange={e=>setTerm(e.target.value)} placeholder="Search articles, topics or tags" className="h-11 w-full border border-slate-300 bg-white pl-9 pr-3 text-sm outline-none focus:border-[#008f68] focus:ring-2 focus:ring-[#008f68]/10"/></label><div className="flex items-center gap-2 overflow-x-auto pb-1" aria-label="Filter blog topics">{tags.slice(0,14).map(x=><button type="button" key={x} onClick={()=>setTag(x)} className={`whitespace-nowrap border px-3 py-2 text-xs font-medium ${tag===x?"border-[#008f68] bg-[#e9f6f2] text-[#006f52]":"border-slate-300 bg-white text-slate-600 hover:border-[#008f68] hover:text-[#008f68]"}`}>{x}</button>)}</div></div>}
  {loading?<div className="py-20 text-center text-sm text-slate-500">Loading articles from Shopify…</div>:!articles.length?<div className="mt-8 border border-dashed border-slate-300 bg-slate-50 p-12 text-center"><BookOpen className="mx-auto text-slate-400" size={36}/><h2 className="mt-4 text-xl font-bold">Your Shopify blog is ready for content</h2><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-slate-500">Create and publish articles in Shopify and they will appear here automatically. The storefront is already wired to the Storefront API blog/article objects.</p></div>:!filtered.length?<div className="mt-8 border border-dashed border-slate-300 bg-slate-50 p-12 text-center"><Search className="mx-auto text-slate-400" size={30}/><h2 className="mt-3 text-xl font-bold">No articles match</h2><p className="mt-1 text-sm text-slate-500">Try another search term or clear the topic filter.</p><button type="button" onClick={()=>{setTerm("");setTag("All")}} className="mt-4 border border-slate-300 bg-white px-4 py-2 text-xs font-semibold">Clear filters</button></div>:<div className="mt-7 grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{filtered.map(a=><Link key={a.id} href={`/blog/${a.blogHandle}/${a.handle}`} className="group overflow-hidden border border-slate-200 bg-white"><div className="aspect-[16/10] overflow-hidden bg-slate-100">{a.image?<img src={a.image.url} alt={a.image.altText||a.title} loading="lazy" className="h-full w-full object-cover object-center transition duration-300 group-hover:scale-105"/>:<div className="grid h-full place-items-center text-slate-400"><BookOpen/></div>}</div><div className="p-5"><div className="flex items-center justify-between gap-3 text-[10px] font-medium uppercase tracking-wider text-slate-500"><span>{a.blogTitle}</span><span>{new Date(a.publishedAt).toLocaleDateString()}</span></div><h2 className="mt-2 line-clamp-2 text-lg font-semibold group-hover:text-[#008f68]">{a.title}</h2><p className="mt-2 line-clamp-3 text-sm leading-6 text-slate-500">{a.excerpt||"Read more from the BuyHoreca Journal."}</p><span className="mt-4 inline-flex items-center gap-1 text-xs font-semibold text-[#008f68]">Read article <ArrowRight size={13}/></span></div></Link>)}</div>}
 </main>}

function BlogArticlePage({article}:{article:BlogArticle}){return <main className="mx-auto max-w-[1100px] px-4 py-8"><div className="text-xs text-slate-500"><Link href="/">Home</Link><span className="mx-2">/</span><Link href="/blog">Blog</Link><span className="mx-2">/</span>{article.title}</div><article className="mt-5 overflow-hidden border border-slate-200 bg-white"><div className="p-6 md:p-10"><div className="text-[10px] font-semibold uppercase tracking-[.16em] text-[#008f68]">{article.blogTitle||"BuyHoreca Journal"}</div><h1 className="mt-2 text-3xl font-semibold leading-tight md:text-4xl lg:text-[2.75rem]">{article.title}</h1><div className="mt-4 flex flex-wrap items-center gap-4 text-xs font-semibold text-slate-500"><span className="inline-flex items-center gap-1"><CalendarDays size={13}/>{new Date(article.publishedAt).toLocaleDateString()}</span>{article.tags.slice(0,5).map(t=><span key={t} className="rounded-full bg-slate-100 px-2.5 py-1">{t}</span>)}<button type="button" onClick={()=>{void navigator.clipboard?.writeText(location.href)}} className="ml-auto inline-flex items-center gap-1 border border-slate-200 px-3 py-2 font-bold text-slate-700" aria-label="Copy article link"><Share2 size={13}/> Share</button></div></div>{article.image&&<div className="aspect-[16/7] bg-slate-100"><img src={article.image.url} alt={article.image.altText||article.title} className="h-full w-full object-cover object-center"/></div>}<div className="prose prose-slate max-w-none px-6 py-8 text-[15px] leading-7 md:px-10" dangerouslySetInnerHTML={{__html:article.contentHtml}}/></article><div className="mt-5 flex items-center justify-between border border-slate-200 bg-white p-5"><Link href="/blog" className="inline-flex items-center gap-1 text-sm font-semibold text-[#008f68]"><ChevronLeft size={16}/> Back to Blog</Link><Link href="/shop" className="inline-flex items-center gap-1 text-sm font-semibold text-[#008f68]">Shop products <ArrowRight size={15}/></Link></div></main>}

