function ContactPage({collections}:{collections:Collection[]}){return <main className="mx-auto max-w-[1100px] px-4 py-10"><div className="grid gap-6 md:grid-cols-2"><div className="border border-slate-200 bg-white p-7 md:p-10"><div className="text-[10px] font-semibold uppercase tracking-widest text-[#008f68]">Contact BuyHoreca</div><h1 className="mt-2 text-3xl font-semibold md:text-4xl">How can we help?</h1><p className="mt-4 text-sm leading-7 text-slate-600">For product questions, commercial requirements, quotations and hospitality supply enquiries, contact the BuyHoreca team.</p><div className="mt-7 grid gap-4 text-sm"><a href="tel:+971509936806" className="flex items-center gap-3 font-bold"><Phone className="text-[#008f68]" size={18}/> +971 50 993 6806</a><a href="tel:+971565334464" className="flex items-center gap-3 font-bold"><Phone className="text-[#008f68]" size={18}/> +971 56 533 4464</a><a href="mailto:info@buyhoreca.com" className="flex items-center gap-3 font-bold"><Mail className="text-[#008f68]" size={18}/> info@buyhoreca.com</a><div className="flex items-start gap-3 font-bold"><MapPin className="mt-0.5 text-[#008f68]" size={18}/>Dubai, U.A.E.</div></div><div className="mt-7 flex flex-wrap gap-3"><Link href="/quote" className="rounded bg-[#008f68] px-5 py-3 text-sm font-semibold text-white">Request a Quote</Link><a href="https://wa.me/971565334464" target="_blank" rel="noreferrer" className="rounded border border-slate-300 px-5 py-3 text-sm font-semibold">WhatsApp</a></div></div><div className="overflow-hidden border border-slate-200 bg-[#0b2b22]"><CompanyImage alt="BuyHoreca hospitality supply" className="bh-company-image h-full min-h-[420px] w-full object-cover object-center"/></div></div></main>}
