 useEffect(()=>{if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||window.matchMedia("(pointer: coarse)").matches||window.innerWidth<769)return;const l=new Lenis({duration:0.8,smoothWheel:true,prevent:(node:Element)=>!!node.closest("[data-lenis-prevent]")});let id=0;const raf=(t:number)=>{l.raf(t);id=requestAnimationFrame(raf)};id=requestAnimationFrame(raf);return()=>{cancelAnimationFrame(id);l.destroy()}},[]);
 useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if(e.key==="Escape"){setQuick(null);setCartOpen(false)}};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey)},[]);
 const add=async(p:Product,v?:Variant,q=1)=>{const selected=v||firstPurchasableVariant(p);if(!selected)return null;if(!p.availableForSale||!isVariantPurchasable(selected)){showToast("This product is out of stock. Please request a quote.");return null;}const stock=typeof selected.quantityAvailable==="number"?selected.quantityAvailable:null;const existing=cart?.lines.find(l=>l.merchandise.id===selected.id)?.quantity||0;if(stock!==null&&existing+q>stock){showToast(`Only ${Math.max(0,stock-existing)} left in stock.`);return null;}let currentId=cartId;try{let d:any;if(!currentId){d=await shopifyFetch(CREATE_CART,{lines:[{merchandiseId:selected.id,quantity:q}]});if(d.cartCreate?.userErrors?.length)throw new Error(d.cartCreate.userErrors[0].message);const next=normCart(d.cartCreate?.cart);if(!next)throw new Error("Unable to create cart");setCart(next);setCartId(next.id);localStorage.setItem("buyhoreca_shopify_cart_id",next.id);setCartOpen(true);setCartPulse(true);showToast(`${p.name} added to cart`);window.setTimeout(()=>setCartPulse(false),520);return next;}d=await shopifyFetch(ADD_LINES,{cartId:currentId,lines:[{merchandiseId:selected.id,quantity:q}]});if(d.cartLinesAdd?.userErrors?.length)throw new Error(d.cartLinesAdd.userErrors[0].message);const next=normCart(d.cartLinesAdd?.cart);if(!next)throw new Error("Unable to update cart");setCart(next);setCartOpen(true);setCartPulse(true);showToast(`${p.name} added to cart`);window.setTimeout(()=>setCartPulse(false),520);return next}catch(err){if(currentId){localStorage.removeItem("buyhoreca_shopify_cart_id");setCartId(null);setCart(null);try{const d:any=await shopifyFetch(CREATE_CART,{lines:[{merchandiseId:selected.id,quantity:q}]});if(d.cartCreate?.userErrors?.length)throw new Error(d.cartCreate.userErrors[0].message);const next=normCart(d.cartCreate?.cart);if(next){setCart(next);setCartId(next.id);localStorage.setItem("buyhoreca_shopify_cart_id",next.id);setCartOpen(true);setCartPulse(true);showToast(`${p.name} added to cart`);window.setTimeout(()=>setCartPulse(false),520);return next}}catch{} }showToast(err instanceof Error?err.message:"We couldn't add this product right now.");return null}};
 const update=async(id:string,q:number)=>{if(!cartId)return;if(q<=0)return remove(id);const line=cart?.lines.find(l=>l.id===id);const max=typeof line?.merchandise.quantityAvailable==="number"?line.merchandise.quantityAvailable:null;if(max!==null&&q>max){showToast(`Only ${max} in stock.`);return;}try{const d:any=await shopifyFetch(UPDATE_LINES,{cartId,lines:[{id,quantity:q}]});if(d.cartLinesUpdate?.userErrors?.length)throw new Error(d.cartLinesUpdate.userErrors[0].message);const next=normCart(d.cartLinesUpdate.cart);if(next){setCart(next);trackEvent("view_cart",{value:next.cost.totalAmount.amount,currency:next.cost.totalAmount.currencyCode,item_count:next.totalQuantity})}}catch(e){showToast(e instanceof Error?e.message:"Unable to update cart")}};
 const remove=async(id:string)=>{if(!cartId)return;try{const d:any=await shopifyFetch(REMOVE_LINES,{cartId,lineIds:[id]});if(d.cartLinesRemove?.userErrors?.length)throw new Error(d.cartLinesRemove.userErrors[0].message);const next=normCart(d.cartLinesRemove.cart);if(next){setCart(next);trackEvent("remove_from_cart",{line_id:id,item_count:next.totalQuantity})}}catch(e){showToast(e instanceof Error?e.message:"Unable to remove item")}};
 const applyDiscount=async(code:string)=>{if(!cartId){showToast("Add a product before applying a discount code.");return false;}try{const d:any=await shopifyFetch(UPDATE_DISCOUNTS,{cartId,discountCodes:code?[code]:[]});if(d.cartDiscountCodesUpdate?.userErrors?.length)throw new Error(d.cartDiscountCodesUpdate.userErrors[0].message);const next=normCart(d.cartDiscountCodesUpdate.cart);if(next){setCart(next);const applied=next.discountCodes.find(x=>x.code.toLowerCase()===code.toLowerCase());if(code&&!applied?.applicable)showToast(`${code} is not applicable to this cart`);else if(code)showToast(`${code} applied`);else showToast("Discount removed");return !!applied?.applicable||!code}return false}catch(e){showToast(e instanceof Error?e.message:"Unable to update discount code");return false}};
 let content:ReactNode;if(pathname==="/track-order")content=<TrackOrderPage/>;else if(pathname==="/account")content=<CustomerAccountPage/>;else if(loading)content=<main className="mx-auto max-w-[1920px] px-4 py-20"><div className="grid gap-3 md:grid-cols-6">{Array.from({length:12}).map((_,i)=><div key={i} className="bh-skeleton h-64 rounded border border-slate-200"/> )}</div></main>;else if(error)content=<SimplePage title="Store temporarily unavailable" text={error}><button type="button" onClick={refresh} className="bh-primary-button mt-6">Try again <RefreshCw size={15}/></button></SimplePage>;else if(pathname==="/")content=<Home bestSelling={homeBestSelling} newest={homeNewest} essentials={homeEssentials} collections={collections} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/shop"||pathname==="/search")content=pathname==="/search"?<SearchPage q={query} categories={collections} onAdd={add} onQuick={setQuick}/>:<Catalog initial={products} collections={collections} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/categories"||pathname==="/collections")content=<CategoryIndex collections={collections}/>;else if(pathname.startsWith("/categories/")){const c=collections.find(x=>x.handle===pathname.split("/")[2]);content=<CategoryLoader handle={pathname.split("/")[2]||""} fallback={c||null} onAdd={add} onQuick={setQuick}/>;}else if(pathname.startsWith("/products/"))content=productLoading?<SimplePage title="Loading product…"/>:product?<ProductPage product={product} collections={collections} onAdd={add} onQuick={setQuick}/>:<SimplePage title="Product not found" text="This product is no longer available through the live Shopify catalogue."><Link href="/shop" className="bh-primary-button mt-6 inline-flex">Back to products <ArrowRight size={15}/></Link></SimplePage>;else if(pathname==="/brands")content=<BrandIndex collections={collections}/>;else if(pathname.startsWith("/brands/")){const handle=decodeURIComponent(pathname.split("/")[2]||"");content=<BrandPage handle={handle} onAdd={add} onQuick={setQuick} collections={collections}/>;}else if(pathname==="/business")content=<BusinessIndex/>;else if(pathname.startsWith("/business/"))content=<BusinessPage name={titleFromSlug(pathname.split("/")[2]||"")} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/cart")content=<CartPage cart={cart} onUpdate={update} onRemove={remove} onDiscount={applyDiscount}/>;else if(pathname==="/wishlist")content=<Wishlist ids={wishlist} products={products} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/compare")content=<ComparePage ids={compare} products={products} onAdd={add} onQuick={setQuick}/>;else if(pathname==="/quote")content=<QuotePage/>;else if(pathname==="/about")content=<AboutPage collections={collections}/>;else if(pathname==="/contact")content=<ContactPage collections={collections}/>;else if(pathname==="/faq")content=<FAQPage/>;else if(pathname==="/shipping")content=<PolicyPage handle="shipping-policy"/>;else if(pathname==="/account")content=<CustomerAccountPage/>;else if(pathname.startsWith("/policies/"))content=<PolicyPage handle={pathname.split("/")[2]||""}/>;else if(pathname==="/blog")content=<BlogIndex/>;else if(pathname.startsWith("/blog/")){const bits=pathname.split("/").filter(Boolean);content=bits.length>=3?<BlogArticleLoader blogHandle={bits[1]} articleHandle={bits[2]}/>:<BlogIndex/>;}else content=<SimplePage title="BuyHoreca" text="Professional HoReCa equipment and supplies for hospitality businesses in the UAE."/>;
