 const reload=async()=>{setLoading(true);try{const next=await getCollection(resolvedHandle,null,activeFacetInputs(selected),collectionSort,collectionReverse);if(next){setCollection(next);setFilters(next.filters||[]) ;setCursor(next.pageInfo?.hasNextPage?next.pageInfo.endCursor:null)}}finally{setLoading(false)}};
 useEffect(()=>{if(!collection?.handle)return;const timer=window.setTimeout(()=>void reload(),0);return()=>window.clearTimeout(timer)},[JSON.stringify(selected),sort]);
