 if(!collection){if(!requested)return <main className="mx-auto max-w-[1920px] px-4 py-14 text-center text-sm text-slate-500">Loading brand…</main>;if(loadError)return <SimplePage title="Brand catalogue temporarily unavailable" text="We could not load this brand’s Shopify collection right now. Please try again shortly, browse other brands, or contact BuyHoreca for help."><button type="button" onClick={()=>window.location.reload()} className="bh-primary-button mt-6">Try again <RefreshCw size={15}/></button><Link href="/brands" className="ml-2 inline-flex h-11 items-center rounded border border-slate-300 px-4 text-sm font-semibold">Browse brands</Link></SimplePage>;if(brandEntry){return <main className="mx-auto max-w-[1000px] px-4 py-10"><div className="rounded-xl border border-slate-200 bg-white p-6 text-center sm:p-10"><div className="mx-auto flex h-28 max-w-[260px] items-center justify-center rounded-lg bg-slate-50 p-5">{brandEntry.logoPath?<img src={brandEntry.logoPath} alt={`${brandEntry.name} logo`} className="max-h-full max-w-full object-contain"/>:<span className="bh-brand-name-mark text-2xl">{brandEntry.name.split(/[\s-]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()}</span>}</div><div className="mt-5 text-[10px] font-semibold uppercase tracking-[.16em] text-[#008f68]">Brand directory</div><h1 className="mt-2 text-3xl font-semibold text-[#0f2630] md:text-4xl">{brandEntry.name}</h1><p className="mx-auto mt-3 max-w-2xl text-sm leading-6 text-slate-600">We’ve added {brandEntry.name} to the BuyHoreca brand directory. Its dedicated product collection is being prepared and will appear here once connected to Shopify.</p><div className="mt-6 flex flex-wrap justify-center gap-3"><Link href="/shop" className="inline-flex h-11 items-center rounded bg-[#008f68] px-5 text-sm font-semibold text-white hover:bg-[#007b5a]">Browse all products <ArrowRight size={15} className="ml-2"/></Link><Link href="/quote" className="inline-flex h-11 items-center rounded border border-slate-300 px-5 text-sm font-semibold hover:border-[#008f68]">Request a quote</Link><Link href="/brands" className="inline-flex h-11 items-center rounded border border-slate-300 px-5 text-sm font-semibold hover:border-[#008f68]">All brands</Link></div></div></main>}return <SimplePage title="Brand collection unavailable" text="This brand does not have a connected collection yet. Browse other brands or contact BuyHoreca for help."><Link href="/brands" className="bh-primary-button mt-6 inline-flex">Browse brands <ArrowRight size={15}/></Link></SimplePage>}
